<?php require '../includes/core.php';$u=require_user(true);$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT t.*,us.name client FROM tickets t JOIN users us ON us.id=t.user_id WHERE t.id=?');$s->execute([$id]);$t=$s->fetch();if(!$t||(false)){http_response_code(404);exit('Chamado não encontrado.');}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf();$action=$_POST['action']??'reply';if($action==='update'&&true){$status=$_POST['status']??'';$priority=$_POST['priority']??'';if(in_array($status,['Aberto','Em andamento','Resolvido','Fechado'],true)&&in_array($priority,['Baixa','Média','Alta','Urgente'],true)){$s=db()->prepare('UPDATE tickets SET status=?,priority=?,assigned_admin_id=? WHERE id=?');$s->execute([$status,$priority,$u['id'],$id]);if($status!==$t['status'])notification_create($t['user_id'],'Status atualizado: chamado #'.$id,'Novo status: '.$status,'user/ticket.php?id='.$id);notify('Chamado atualizado.');go('admin/ticket.php?id='.$id);}else $error='Valores inválidos.';}else{$msg=trim($_POST['message']??'');if(strlen($msg)<2)$error='Digite uma mensagem.';else{$s=db()->prepare('INSERT INTO ticket_messages(ticket_id,user_id,message) VALUES(?,?,?)');$s->execute([$id,$u['id'],$msg]);notification_create($t['user_id'],'Nova resposta no chamado #'.$id,mb_substr($msg,0,180),'user/ticket.php?id='.$id);notify('Mensagem enviada.');go('admin/ticket.php?id='.$id);}}}$s=db()->prepare('SELECT m.*,us.name sender,us.role FROM ticket_messages m JOIN users us ON us.id=m.user_id WHERE m.ticket_id=? ORDER BY m.id');$s->execute([$id]);layout_start('Chamado #'.$id,$u);?><div class="actions"><a class="btn secondary" href="tickets.php">← Voltar</a></div><div class="card"><span class="kicker">CHAMADO #<?=$id?></span><h1><?=h($t['subject'])?></h1><p class="muted">Cliente: <?=h($t['client'])?> · <?=h($t['category'])?></p><?=status_badge($t['status'])?><p><?=nl2br(h($t['description']))?></p></div><?php if(true):?><div class="card" style="margin-top:17px"><h2>Atualizar atendimento</h2><form method="post"><input type="hidden" name="csrf" value="<?=token()?>"><input type="hidden" name="action" value="update"><div class="split"><label class="field">Status<select name="status"><?php foreach(['Aberto','Em andamento','Resolvido','Fechado'] as $x):?><option <?=($t['status']===$x?'selected':'')?>><?=h($x)?></option><?php endforeach;?></select></label><label class="field">Prioridade<select name="priority"><?php foreach(['Baixa','Média','Alta','Urgente'] as $x):?><option <?=($t['priority']===$x?'selected':'')?>><?=h($x)?></option><?php endforeach;?></select></label></div><button class="btn">Salvar alterações</button></form></div><?php endif;?><div class="card" style="margin-top:17px"><h2>Conversa</h2><?php foreach($s as $m):?><div class="msg <?=$m['role']==='admin'?'staff':''?>"><strong><?=h($m['sender'])?></strong> <small class="muted"><?=date('d/m H:i',strtotime($m['created_at']))?></small><p><?=nl2br(h($m['message']))?></p></div><?php endforeach;?><form method="post"><input type="hidden" name="csrf" value="<?=token()?>"><input type="hidden" name="action" value="reply"><label class="field">Escrever mensagem<textarea name="message" required></textarea></label><button class="btn">Enviar resposta</button></form></div><?php layout_end();?>